  insert into public.boq_lines (boq_id, qty, loc, sort, kind, title, descr, unit, div_code, ls_code, refs) values (nb, 1, $t$كاسرات الألمنيوم وأغطية الشفتات (SOW قسم 5 — البندان 4.3 و4.4).$t$, 160, 'free', $t$الكاسرات وأغطية الفتحات من الألمنيوم$t$, $t$توريد وتركيب كاسرات وشبابيك تهوية (Louvers) من الألمنيوم المبثوق المدهون بودرة بوليستر بسماكة لا تقل عن 80 ميكرون باللون المعتمد، بشفرات مانعة لدخول المطر وشبك حماية من الطيور والحشرات، للفتحات الميكانيكية والواجهات حسب المخططات؛ وتوريد وتركيب أغطية وفلاشينج من صفائح الألمنيوم المدهون لتغطية الشفتات والفتحات على السطح وحواف التقاء المواد، بالتثبيت والإحكام بالسيليكون المناسب للأعمال الخارجية؛ مع تقديم العينات ومخططات الورشة للاعتماد قبل التصنيع. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$, 'مقطوعية', $t$08$t$, null, array[$t$08 91 19$t$,$t$23 37 19$t$,$t$07 62 13$t$]::text[]);
  insert into public.boq_lines (boq_id, qty, loc, sort, kind, title, descr, unit, div_code, ls_code, refs) select nb, 1, $t$الأبواب المعدنية والخشبية المفردة (SOW 8.1) والمزدوجة (8.2). الأبواب الزجاجية ضمن بند الواجهات والقواطع الزجاجية.$t$, 170, 'free', $t$الأبواب المعدنية والخشبية والأقفال$t$, $t$توريد وتركيب جميع الأبواب المفردة والمزدوجة حسب جدول الأبواب والمخططات: الأبواب المعدنية بضلفة 47 مم من صاج 1.6 مم وحلق 2.0 مم بتشطيب Flush، وحشوة صوف صخري مع مقويات للأبواب المقاومة للحريق (60/90 دقيقة حسب المخطط) وخلايا نحل لغيرها؛ والأبواب الخشبية بضلفة مصمتة (Solid Core) بتشطيب HPL أو قشرة خشبية حسب جدول التشطيبات، مقاومة للصدمات وسهلة التنظيف للمناطق السريرية؛ مع الإكسسوارات والمفصلات والغالقات وأجهزة الخروج Grade 1، ونوافذ الرؤية بزجاج أمان حيث وردت، وحماية Kick Plate بارتفاع لا يقل عن 90 سم (CS Group)؛ وعرض صافٍ لا يقل عن 95 سم للمفرد و180 سم للمزدوج وفق دليل الوصول الشامل؛ وأبواب مخارج الطوارئ المقاومة للحريق تفتح للخارج بذراع خروج سريع مربوط بإنذار الحريق؛ وأقفال إلكترونية SALTO بقفل Mortise لغرف الكهرباء والاتصالات والميكانيكا والغازات الطبية؛ ونظام مفاتيح ماستر مع صناديق مفاتيح مرقمة. يُعتمد نوع كل باب وقفل قبل التوريد. المصنّعون المعتمدون للأبواب المعدنية: HÖRMANN، الكحيمي، الدريس. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$, 'مقطوعية', div_code, code, coalesce(refs, '{}') || array[$t$08 14 16$t$]::text[] from public.ls_items where code = $t$LS-54$t$;
  insert into public.boq_lines (boq_id, qty, loc, sort, kind, title, descr, unit, div_code, ls_code, refs) values (nb, 1, $t$الأبواب المبطنة بالرصاص المفردة والمزدوجة (SOW 8.5–8.6)، والنافذة الرصاصية (8.8)، وتبطين جدران غرفة الأشعة (9.5.5).$t$, 180, 'free', $t$التدريع الإشعاعي لغرفة الأشعة (الجدران والأبواب والنافذة)$t$, $t$توريد وتركيب التدريع الإشعاعي لغرفة الأشعة حسب دراسة الحماية الإشعاعية المعتمدة: تبطين الجدران (والأسقف والأرضيات حيث تتطلب الدراسة) بألواح الرصاص بالسماكة المكافئة المحددة في الدراسة مع تراكب الفواصل وتغطية فتحات التمديدات؛ وأبواب خشبية مبطنة بالرصاص مفردة ومزدوجة بالمكافئ الرصاصي نفسه بحلوقها وإكسسواراتها؛ ونافذة مراقبة من الزجاج الرصاصي بإطارها؛ ولوحة تحذير ومصباح «الأشعة قيد التشغيل» عند المدخل؛ مع تقديم دراسة الحماية من جهة مؤهلة واعتمادها من هيئة الرقابة النووية والإشعاعية، وقياس مستويات الإشعاع بعد التركيب بتقرير معتمد قبل التشغيل. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$, 'مقطوعية', $t$13$t$, null, array[$t$13 49 13$t$,$t$13 49 16$t$,$t$13 49 19$t$,$t$08 34 49$t$]::text[]);
  insert into public.boq_lines (boq_id, qty, loc, sort, kind, title, descr, unit, div_code, ls_code, refs) select nb, 1, $t$الأبواب الأوتوماتيكية (SOW 8.7) بالعدد الوارد في جدول الأبواب.$t$, 190, 'free', $t$الأبواب الأوتوماتيكية$t$, $t$توريد وتركيب الأبواب الانزلاقية الأوتوماتيكية في المواقع المحددة في جدول الأبواب (ومنها المدخل الرئيسي): زجاج مزدوج مقسّى 8+8 مم بفراغ هوائي، وإطار ألمنيوم مدهون بودرة أو أنودايز باللون المعتمد، وعرض ممر صافٍ يسمح بعبور الكراسي المتحركة والنقالات؛ محرك Dorma EL 301 أو ما يعادله لخدمة الاستخدام الكثيف، وحساسات حركة على الوجهين وحساس أمان ضد الاصطدام، ومفتاح أوضاع (أوتوماتيك / مفتوح دائماً / مغلق / اتجاه واحد)؛ وربطها بإنذار الحريق لتفتح فتحاً كاملاً دائماً عند الإنذار (Fail-Safe)، وبطارية احتياطية تشغّلها لمدة لا تقل عن ساعة؛ مع ضمان لا يقل عن سنتين على المحرك ونظام التشغيل. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$, 'مقطوعية', div_code, code, coalesce(refs, '{}') || '{}'::text[] from public.ls_items where code = $t$LS-55$t$;
  insert into public.boq_lines (boq_id, qty, loc, sort, kind, title, descr, unit, div_code, ls_code, refs) select nb, 1, $t$النوافذ CW-01 بمقاس 6.5×0.6 م (28 طقماً) وCW-02 بمقاس 2.0×0.6 م (32 طقماً) (SOW 8.9–8.10)، والجدار الساتر للواجهة الأمامية فقط (8.11)، والقواطع الزجاجية (8.12)، والأبواب الزجاجية المفردة والمزدوجة (8.3–8.4).$t$, 200, 'free', title, descr, coalesce(nullif(unit, ''), 'مقطوعية'), div_code, code, refs from public.ls_items where code = $t$LS-56$t$;
