  insert into public.boq_lines (boq_id, qty, loc, sort, kind, title, descr, unit, div_code, ls_code, refs) select nb, 1, $t$طبقة التسوية (SOW 9.1.1)، والفينيل (9.2.1)، والموكيت للمكاتب وغرف الاجتماعات ومناطق الصلاة (9.2.2)، والإيبوكسي للأرضيات (9.2.3) ولجدران المواقع المحددة (9.5.6).$t$, 220, 'free', title, descr, coalesce(nullif(unit, ''), 'مقطوعية'), div_code, code, refs from public.ls_items where code = $t$LS-58$t$;
  insert into public.boq_lines (boq_id, qty, loc, sort, kind, title, descr, unit, div_code, ls_code, refs) select nb, 1, $t$بورسلان أرضيات المناطق الرطبة (SOW 9.2.2) وجدرانها (9.5.3)، ورخام كرارا (Carrara) للدرج (9.5.1)، وجرانيت المدخل الأمامي (9.2.5 — المقاس كما ورد في نطاق العمل ويُعتمد من المخططات). تيرازو السطح ضمن بند عزل الأسطح.$t$, 230, 'free', title, descr, coalesce(nullif(unit, ''), 'مقطوعية'), div_code, code, refs from public.ls_items where code = $t$LS-59$t$;
