  insert into public.boq_lines (boq_id, qty, loc, sort, kind, title, descr, unit, div_code, ls_code, refs) values (nb, 1, $t$القواطع الجبسية (SOW 9.4.1).$t$, 250, 'free', $t$القواطع الجبسية$t$, $t$توريد وتركيب القواطع الداخلية من ألواح الجبس على هياكل معدنية مجلفنة بالسماكات وأنواع الألواح المحددة في المخططات (عادي، مقاوم للرطوبة في المناطق الرطبة، مقاوم للحريق حيث يلزم)، بكامل الارتفاع حتى السقف الإنشائي، مع حشوة عازلة للصوت من الصوف الصخري، وتقويات داخلية خلف الأجهزة والخزائن والمعلقات الجدارية، والزوايا المعدنية والمعجون والتجهيز للدهان، وإحكام الفراغات والاختراقات بمواد مقاومة للحريق حيث يلزم. الألواح: USG أو MADA. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$, 'مقطوعية', $t$09$t$, null, array[$t$09 21 16$t$,$t$09 22 16$t$]::text[]);
