  insert into public.boq_lines (boq_id, qty, loc, sort, kind, title, descr, unit, div_code, ls_code, refs) select nb, 1, $t$نجارة SOW 6.1–6.5 و6.7–6.12. التكسيات الخشبية (6.6) ضمن بند حماية الحوائط والديكورات.$t$, 320, 'free', $t$الكاونترات والخزائن والنجارة الثابتة$t$, $t$توريد وتركيب الكاونترات والخزائن الثابتة حسب المخططات من خشب شيبورد صناعي مقاوم للرطوبة بحواف ABS وأسطح من الرخام الصناعي (Solid Surface)، بإكسسوارات ألمانية وأدراج بإغلاق هادئ (Soft Close)، ويُعتمد التصميم والعينات من مهندس المشروع، وتشمل: كاونتر الاستقبال بواجهة رخام صناعي مزدوج السماكة وجزء منخفض لا يزيد عن 80 سم لمستخدمي الكراسي المتحركة؛ كاونتر الصيدلية ووحدات أرفف الصيدلية؛ خزائن بمغاسل لغرف الملاحظة وغرف التقييم السريع (RAZ)؛ خزائن المختبر وأسطحه المقاومة للكيماويات؛ كاونتر المقهى؛ خزائن المطبخ؛ أسطح مغاسل دورات المياه (Vanity) بالمغاسل والخلاطات والمرايا؛ أسطح كوريان بخزائن سفلية لغرف الأدوية والأدوات النظيفة والمتسخة؛ وحدات التخزين في المستودعات؛ وحوض ستانلس ستيل بسطحه لغرفة النفايات الطبية. الخلاطات: Ideal Standard أو Grohe حصراً. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$, 'مقطوعية', div_code, code, coalesce(refs, '{}') || array[$t$12 35 53$t$,$t$12 35 55$t$,$t$12 36 63$t$,$t$12 35 74$t$]::text[] from public.ls_items where code = $t$LS-67$t$;
  insert into public.boq_lines (boq_id, qty, loc, sort, kind, title, descr, unit, div_code, ls_code, refs) select nb, 1, $t$الستائر الدوارة اليدوية (SOW 10.3.1) وستائر خصوصية المرضى (10.3.2). مكاتب الموظفين والنباتات الداخلية غير مشمولة (الأثاث مستبعد من نطاق العمل).$t$, 330, 'free', $t$الستائر الطبية والستائر الدوارة$t$, $t$توريد وتركيب ستائر خصوصية المرضى (Cubicle Curtains) بأقمشة مخصصة للاستخدام الطبي مقاومة للاشتعال، بسككها السقفية ومنزلقاتها، لغرف الفحص والملاحظة والإجراءات وكبائن العلامات الحيوية حسب المخططات، مع طقمي أقمشة احتياطيين لكل موقع؛ وستائر دوارة (Roller Blinds) يدوية: معتمة (Blackout) لنوافذ العيادات وغرف الفحص، وشفافة (See-Through) للمدخل والمكاتب؛ من مورد معتمد بعد اعتماد العينات. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$, 'مقطوعية', div_code, code, coalesce(refs, '{}') || array[$t$10 21 23$t$,$t$10 21 24$t$,$t$12 24 13$t$]::text[] from public.ls_items where code = $t$LS-68$t$;
  insert into public.boq_lines (boq_id, qty, loc, sort, kind, title, descr, unit, div_code, ls_code, refs) select nb, 1, $t$مصعد الموظفين GF-16 ومصعد الزوار GF-76 (SOW 14.1–14.2).$t$, 340, 'free', $t$المصاعد$t$, $t$توريد وتركيب وتشغيل مصعدين حسب المخططات من Schindler حصراً: مصعد الموظفين (GF-16) بفتحة بئر إنشائية 2.75×3.45 م، ومصعد الزوار (GF-76) بفتحة بئر 2.50×2.80 م، بالحمولات والسرعات ومقاسات الكابينة المناسبة لأبعاد البئر واستخدام المنشأة الصحية وفق كود البناء السعودي، بجميع الإكسسوارات والمفاتيح والتشطيبات الداخلية والديكورات التي يختارها مهندس المشروع، شاملاً تجهيز البئر والتجهيزات الكهربائية والربط بإنذار الحريق (الاستدعاء عند الحريق) والتغذية من المولد الاحتياطي، والاختبار والاعتماد من الجهات المختصة قبل التسليم، والصيانة الوقائية خلال فترة الضمان. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$, 'مقطوعية', div_code, code, coalesce(refs, '{}') || '{}'::text[] from public.ls_items where code = $t$LS-69$t$;
  insert into public.boq_lines (boq_id, qty, loc, sort, kind, title, descr, unit, div_code, ls_code, refs) select nb, 1, $t$مواسير الإطفاء (SOW 21.1.1) والمحابس (21.1.2) والرشاشات (21.1.4) ومحبس الإنذار (Alarm Check Valve) (21.1.6) ومحابس المناطق (21.1.7).$t$, 350, 'free', title, descr, coalesce(nullif(unit, ''), 'مقطوعية'), div_code, code, refs from public.ls_items where code = $t$LS-70$t$;
