  insert into public.boq_lines (boq_id, qty, loc, sort, kind, title, descr, unit, div_code, ls_code, refs) select nb, 1, $t$مواسير المياه الباردة والحارة PPR (SOW 22.1.1–22.1.2) ومحابسها (22.1.3)، ومواسير الصرف UPVC (22.2.1)، وغرف التفتيش للصرف والأمطار (22.2.2)، والجلي تراب (22.2.5)، وخزانات المياه العلوية على السطح (22.1.8).$t$, 380, 'free', title, descr, coalesce(nullif(unit, ''), 'مقطوعية'), div_code, code, refs from public.ls_items where code = $t$LS-73$t$;
  insert into public.boq_lines (boq_id, qty, loc, sort, kind, title, descr, unit, div_code, ls_code, refs) select nb, 1, $t$الأطقم الصحية (SOW 22.2.3)، ومواضئ الرجال والنساء بخلاطاتها وتصريفها (22.2.4).$t$, 390, 'free', title, descr, coalesce(nullif(unit, ''), 'مقطوعية'), div_code, code, refs from public.ls_items where code = $t$LS-74$t$;
  insert into public.boq_lines (boq_id, qty, loc, sort, kind, title, descr, unit, div_code, ls_code, refs) select nb, 1, $t$السخانات 30 لتراً (SOW 22.1.5)، ووحدة التيسير (22.1.6)، ومضخات المياه (22.1.7)، ومضخات الري (22.2.3 — الري).$t$, 400, 'free', $t$سخانات المياه ومضخات الضغط والري ومعالجة المياه$t$, $t$توريد وتركيب وتشغيل سخانات المياه الكهربائية بسعة 30 لتراً (A.O. Smith) للمغاسل ونقاط الاستخدام حسب المخططات، بمفاتيح العزل وصمامات الأمان والتصريف؛ ومجموعة مضخات ضغط (Booster) من Grundfos (CM/CME) من مضختين عاملة واحتياطية بإقلاع متبادل وتحكم بالسرعة وخزان ضغط ولوحة تشغيل بمكونات ABB أو Schneider، بسعة تُحسب من المقاول وتُعتمد؛ ومضخات ري المسطحات الخضراء (Grundfos CM/CME) بمنظم الضغط وفلتر الشوائب ولوحة التحكم؛ ووحدة تيسير المياه (Softener) مزدوجة بسعة تُحسب من تحليل المياه واستهلاك المركز، بإعادة التوليد الآلي وخزان الملح؛ شاملاً القواعد والشاسيه والمحابس ومحابس عدم الرجوع والمواسير، مع تقديم الحسابات للاعتماد. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$, 'مقطوعية', div_code, code, coalesce(refs, '{}') || array[$t$22 31 16$t$,$t$22 33 33$t$]::text[] from public.ls_items where code = $t$LS-75$t$;
  insert into public.boq_lines (boq_id, qty, loc, sort, kind, title, descr, unit, div_code, ls_code, refs) select nb, 1, $t$نظام الغازات الطبية كاملاً (SOW 22.3.1–22.3.8).$t$, 410, 'free', $t$نظام الغازات الطبية$t$, $t$توريد وتركيب واختبار وتشغيل نظام الغازات الطبية حسب المخططات لخدمة الأكسجين (O2) وأكسيد النيتروز (N2O) والهواء الطبي (MA4) والشفط الطبي (Vacuum) وطرد غازات التخدير (AGSS): مواسير النحاس الطبي المنظفة لخدمة الأكسجين (EN 13348) بأقطار 15 و22 و28 مم بوصلات ملحومة بالفضة تحت النيتروجين؛ وصمامات الكرة الخطية بالأقطار نفسها؛ وصناديق صمامات المناطق (AVSU) لثلاثة غازات ولخمسة غازات بلوحات إنذارها؛ ومخارج الغازات الجدارية بالمعيار البريطاني (BS) للأكسجين وأكسيد النيتروز والهواء الطبي والشفط، ومخارج AGSS بنظام فنتوري؛ ومحطة هواء طبي بضاغطين لولبيين (Duplex Screw) بالمجففات والمرشحات؛ ومحطة شفط طبي مزدوجة (Duplex)؛ ومشعبات الأسطوانات: مشعب أوتوماتيكي للأكسجين 2×4 ولأكسيد النيتروز 2×2، ومشعبات احتياطية للأكسجين 2×2 وللهواء الطبي 2×2 ولأكسيد النيتروز 2×1؛ ووحدات رأس السرير (Bed Head Units) لغرف الملاحظة بمخارج الغازات والكهرباء والإنارة ونداء التمريض؛ وتجهيز غرفة الغازات الطبية وتهويتها وتخزين الأسطوانات؛ مع الاختبارات حسب HTM 02-01 أو NFPA 99 (الضغط، التسرب، التقاطع، النقاء، تحديد الهوية) بشهادة اعتماد من طرف ثالث قبل التشغيل. المصنّعون المعتمدون: BeaconMedaes أو Amico أو Dräger للشبكة والمخارج والصناديق والمشعبات، وBeaconMedaes أو Atlas Copco لمحطتي الهواء والشفط. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$, 'مقطوعية', div_code, code, coalesce(refs, '{}') || array[$t$22 61 13$t$,$t$22 61 19$t$,$t$22 62 13$t$,$t$22 62 19$t$,$t$22 62 23$t$,$t$22 63 13$t$,$t$22 63 23$t$,$t$22 63 29$t$,$t$22 63 33$t$,$t$22 63 36$t$,$t$22 63 53$t$,$t$11 73 13$t$]::text[] from public.ls_items where code = $t$LS-76$t$;
  insert into public.boq_lines (boq_id, qty, loc, sort, kind, title, descr, unit, div_code, ls_code, refs) select nb, 1, $t$وحدات الهواء النقي DX (SOW 23.1)، ووحدات FCU DX (23.2)، وCAV/VAV (23.4)، والناشرات (23.5)، وشبكات الهواء النقي (23.6)، والمخمدات (23.7)، ومجاري الهواء (23.8)، وأجهزة مراقبة فرق الضغط لغرف العزل والإنعاش والإجراءات (23.9). الموازنة ضمن بند الاختبار والتشغيل.$t$, 420, 'free', $t$وحدات الهواء النقي ووحدات التكييف (DX) ومجاري الهواء$t$, $t$توريد وتركيب وتشغيل منظومة التكييف حسب المخططات وجدول المعدات: وحدات الهواء النقي (Fresh Air Units) بنظام التمدد المباشر (DX)، ووحدات الملفات (FCU) بنظام DX بوحداتها الخارجية، وصناديق التدفق الثابت والمتغير (CAV/VAV)، بالسعات ومعدلات الهواء حسب حساب أحمال التبريد على 46°م ومعدلات تغيير الهواء وفروق الضغط وفق ASHRAE 170، بفلاتر عالية الكفاءة متوافقة مع ASHRAE 170 وفلاتر أولية قابلة للغسيل ومصيدة رمل عند مآخذ الهواء الخارجي، ومصائد التكثف وعوازل الاهتزاز؛ ومجاري الهواء (تغذية وراجع وهواء نقي) من الصاج المجلفن عيار 24 بوصلات مرنة مقاومة للاشتعال، وعزل صوتي داخلي غير ليفي، وعزل فيبرجلاس داخلي 48 كجم/م³ سماكة 1 بوصة، وخارجي 64 كجم/م³ سماكة 1.5 بوصة مغلف بألمنيوم 0.8 مم على السطح؛ ومخمدات تحكم بالهواء Opposed Blade، ومخمدات حريق ودخان بتصنيف ساعتين معتمدة UL/FM بصناديق فحصها؛ والناشرات وشبكات الراجع وشبكات الهواء النقي (Louvers)؛ وأجهزة مراقبة فرق الضغط (DPM) بشاشة وإنذار عند غرف العزل والإنعاش والإجراءات؛ وفق ASHRAE وSMACNA وNFPA؛ واختبار المجاري بالدخان والتشغيل التجريبي. الماركات المعتمدة للوحدات: York أو LG أو Gree. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$, 'مقطوعية', div_code, code, coalesce(refs, '{}') || array[$t$23 82 19$t$,$t$23 36 00$t$,$t$23 09 33$t$,$t$23 37 19$t$,$t$23 33 13$t$,$t$23 33 33$t$]::text[] from public.ls_items where code = $t$LS-77$t$;
  insert into public.boq_lines (boq_id, qty, loc, sort, kind, title, descr, unit, div_code, ls_code, refs) select nb, 1, $t$مراوح الشفط (SOW 23.3).$t$, 430, 'free', $t$مراوح الشفط$t$, $t$توريد وتركيب وتشغيل مراوح الشفط حسب جدول المعدات: مراوح سطحية Downblast Centrifugal (Greenheck أو Loren Cook) لدورات المياه وغرف النظافة والنفايات الطبية والميكانيكا وغرف العزل حيث وردت، بتشغيل مستمر على قواعد أصلية وعوازل اهتزاز وصمام عدم رجوع، ودكت مستقل لكل دورة مياه حتى السطح وأكمام حريق ومانع حريق عند اختراق البلاطات؛ وربط المراوح بنظام إدارة المبنى وإنذار الحريق حسب مصفوفة التشغيل. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$, 'مقطوعية', div_code, code, coalesce(refs, '{}') || array[$t$23 34 23$t$]::text[] from public.ls_items where code = $t$LS-78$t$;
  insert into public.boq_lines (boq_id, qty, loc, sort, kind, title, descr, unit, div_code, ls_code, refs) values (nb, 1, $t$نظام إدارة المبنى (SOW 25.1).$t$, 440, 'free', $t$نظام إدارة المبنى (BMS)$t$, $t$توريد وتركيب وتشغيل نظام إدارة المبنى (BMS) متكامل: وحدات التحكم الرقمي المباشر (DDC) والحساسات والمشغلات والثرموستات، وواجهات الربط مع وحدات التكييف ومراوح الشفط والمضخات والمولد ومفتاح التحويل الآلي وخزانات المياه وأجهزة مراقبة فرق الضغط وحالة إنذار الحريق، ومحطة عمل مركزية بالبرامج والطابعة، والمواسير والأسلاك؛ مع برمجة الجداول والإنذارات والتقارير، وتقديم قائمة النقاط (Points List) للاعتماد قبل التنفيذ، والاختبار والتشغيل والتدريب. من مصنّع تُقدَّم بياناته للاعتماد قبل التوريد. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$, 'مقطوعية', $t$25$t$, null, array[$t$23 09 23$t$,$t$23 09 13$t$]::text[]);
  insert into public.boq_lines (boq_id, qty, loc, sort, kind, title, descr, unit, div_code, ls_code, refs) values (nb, 1, $t$وحدة RMU (SOW 26.1)، والمحول (26.2)، وكابلات الجهد المتوسط (26.10). يُنسق مع بند توصيل الخدمات العامة.$t$, 450, 'free', $t$وحدة الحلقة الرئيسية (RMU) والمحول وكابلات الجهد المتوسط$t$, $t$توريد وتركيب واختبار وتشغيل وحدة الحلقة الرئيسية (RMU) للجهد المتوسط، ومحول التوزيع بالقدرة حسب دراسة الأحمال المعتمدة ونسبة الاحتياطي، وكابلات الجهد المتوسط بنهاياتها ووصلاتها، وفق اشتراطات الشركة السعودية للكهرباء ومواصفاتها؛ شاملاً غرفة المحول أو قاعدته وفتحات التهوية والتأريض والحماية، والاختبارات المصنعية والموقعية، والتسليم والتوصيل مع الشركة. المصنّعون المعتمدون من القائمة المعتمدة لدى الشركة السعودية للكهرباء: وحدة الحلقة Lucy أو Schneider أو Hitachi Energy، والمحول الفنار أو الشركة السعودية للمحولات أو Hitachi Energy. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$, 'مقطوعية', $t$26$t$, null, array[$t$26 13 16$t$,$t$26 12 16$t$,$t$26 12 19$t$,$t$26 05 13$t$,$t$26 05 14$t$]::text[]);
  insert into public.boq_lines (boq_id, qty, loc, sort, kind, title, descr, unit, div_code, ls_code, refs) values (nb, 1, $t$المولد (SOW 26.3) ومفتاح التحويل الآلي (26.4).$t$, 460, 'free', $t$المولد الاحتياطي ومفتاح التحويل الآلي$t$, $t$توريد وتركيب وتشغيل مولد ديزل احتياطي بمظلة صامتة بالقدرة حسب دراسة الأحمال الأساسية للمركز (الإنارة والقوى الحرجة، التكييف للمناطق الحرجة، مضخات الحريق والمياه، المصاعد، الغازات الطبية، الأنظمة التقنية) مع احتياطي مستقبلي، بخزان وقود يكفي التشغيل المتواصل للمدة المعتمدة، ونظام العادم والكاتم، والقاعدة وعوازل الاهتزاز، ولوحة التحكم والمراقبة عن بعد والربط بنظام إدارة المبنى؛ ومفتاح التحويل الآلي (ATS) بالسعة المناسبة؛ مع اختبار التحميل الكامل بحمل صناعي (Load Bank) وزمن التحويل، وفق NFPA 110 ومتطلبات الدفاع المدني. المصنّعون المعتمدون: المولد Cummins أو Caterpillar أو FG Wilson أو MTU، ومفتاح التحويل ASCO أو Cummins أو ABB. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$, 'مقطوعية', $t$26$t$, null, array[$t$26 32 13$t$,$t$26 32 23$t$,$t$26 32 26$t$,$t$26 32 29$t$,$t$26 36 23$t$]::text[]);
  insert into public.boq_lines (boq_id, qty, loc, sort, kind, title, descr, unit, div_code, ls_code, refs) select nb, 1, $t$اللوحات الرئيسية والفرعية (SOW 26.5)، ولوحات MCC (26.6)، ولوحات الإنارة والقوى والتكييف (26.7)، وكابلات الجهد المنخفض (26.9). سعة القاطع الرئيسي حسب دراسة الأحمال المعتمدة لهذا المركز.$t$, 470, 'free', title, descr, coalesce(nullif(unit, ''), 'مقطوعية'), div_code, code, refs from public.ls_items where code = $t$LS-79$t$;
