  insert into public.boq_lines (boq_id, qty, loc, sort, kind, title, descr, unit, div_code, ls_code, refs) select nb, 1, $t$كبينة الإذاعة بالمضخمات والخلاطات والمايكروفون (SOW 27.3.1)، والسماعات السقفية (27.3.2). الشاشات الرقمية بند اختياري مستقل.$t$, 540, 'free', $t$نظام الإذاعة الداخلية والإخلاء الصوتي$t$, $t$توريد وتركيب واختبار نظام الإذاعة الداخلية والإخلاء الصوتي (Bosch Praesideo/Plena أو DSPPA): الكبينة المركزية والمضخمات والخلاطات بقدرات تغطي جميع المناطق، ووحدة التحكم ومايكروفون النداء في الاستقبال، والسماعات السقفية ومفاتيح التحكم بالصوت، والتقسيم إلى مناطق نداء مستقلة، بكابلات مقاومة للحريق منخفضة الدخان (LSZH)، والربط بإنذار الحريق لرسائل الإخلاء؛ واختبار التغطية ومستوى الصوت لكل منطقة. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$, 'مقطوعية', div_code, code, coalesce(refs, '{}') || '{}'::text[] from public.ls_items where code = $t$LS-85$t$;
  insert into public.boq_lines (boq_id, qty, loc, sort, kind, title, descr, unit, div_code, ls_code, refs) values (nb, 1, $t$نظام MATV (SOW 27.2.1).$t$, 550, 'free', $t$نظام التلفزة المركزية (MATV)$t$, $t$توريد وتركيب واختبار نظام التلفزة المركزية (MATV) حسب المخططات: الأطباق والهوائيات ووحدة الرأس (Head-End) والمضخمات والموزعات وكابلات التوزيع ومخارج التلفاز في مناطق الانتظار والمواقع المحددة، مع ضبط القنوات المعتمدة واختبار جودة الإشارة عند كل مخرج. تلتزم أي شاشة تُورَّد ضمن هذا النظام بمعيار التجمع للشاشات الرقمية AAHC-FM-STD-DIGITAL-SIGNAGE-001. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$t$, 'مقطوعية', $t$27$t$, null, array[$t$27 41 33$t$]::text[]);
